#define LIGHTS 4
#define LAYERS 3
#define COMPLEXITY 2.0

// Hash function for noise
float hash(vec2 p) {
    p = fract(p * vec2(234.34, 435.345));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

// 2D noise function
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Smooth interpolation
    vec2 u = f * f * (3.0 - 2.0 * f);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, u.x),
              mix(c, d, u.x), u.y);
}

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos(6.28318 * (c * t + d));
}

float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    for(int i = 0; i < 5; i++) {
        f += amp * noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

vec2 rotate(vec2 p, float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = COMPLEXITY * (2.0 * fragCoord.xy - iResolution.xy) / iResolution.y;
    vec2 mouse = COMPLEXITY * (2.0 * iMouse.xy - iResolution.xy) / iResolution.y;

    vec3 finalColor = vec3(0.0);

    for(int layer = 0; layer < LAYERS; layer++) {
        float layerOffset = float(layer) * 0.5;

        for(int i = 0; i < LIGHTS; i++) {
            float timeOffset = float(i) * 3.14159 / float(LIGHTS) + layerOffset;

            vec2 offset = vec2(
                cos(iTime * 0.5 + timeOffset) * mouse.x + 
                sin(iTime * 0.3) * 0.5,
                sin(iTime * 0.4 + timeOffset) * mouse.y + 
                cos(iTime * 0.6) * 0.5
            );

            vec2 rotatedUv = rotate(uv, iTime * 0.1 + float(i) * 0.2);
            vec2 distortedUv = rotatedUv + fbm(rotatedUv * 0.5 + iTime * 0.1) * 0.2;

            float light = 0.15 / distance(normalize(distortedUv), distortedUv);
            float radius = 1.0 + fbm(vec2(iTime * 0.2 + float(i))) * 0.5;

            if(length(distortedUv) < radius) {
                light *= 0.15 / distance(normalize(distortedUv-offset), distortedUv-offset);
                vec3 light_color = palette(float(i) / float(LIGHTS) + iTime * 0.1);
                finalColor = max(finalColor, light * light_color * (1.0 - float(layer) * 0.2));
            }
        }
    }

    // Post processing
    finalColor *= 1.0 + 0.2 * sin(iTime + uv.xyx + vec3(0,2,4));
    finalColor += pow(finalColor, vec3(2.0)) * 0.4;

    // Vignette
    float vignette = length(uv * 0.5);
    finalColor *= smoothstep(1.5, 0.5, vignette);

    // Color correction
    finalColor = pow(finalColor, vec3(0.8));
    finalColor = mix(finalColor, smoothstep(0.0, 1.0, finalColor), 0.3);

    fragColor = vec4(finalColor, 1.0);
}
